                a[k] = node.val;
                if (node.left != null) queue.add(node.left);
                if (node.right != null) queue.add(node.right);
            }
            for (int i = 0; i < a.length; i++) {
                int min = i;
                for (int j = i + 1; j < a.length; j++) if (a[j] < a[min]) min = j;
                if (min != i) { int t = a[i]; a[i] = a[min]; a[min] = t; ops++; }
            }
        }
        return ops;
    }
}

